class ThroatField:
    values: np.ndarray
    label: str

    def __array__(self, dtype=None) -> np.ndarray:
        return np.asarray(self.values, dtype=dtype)

    @property
    def shape(self) -> tuple[int, ...]:
        return np.asarray(self.values).shape

    def __getitem__(self, index):
        return np.asarray(self.values)[index]


def make_throat_field(values: Iterable[float], label: str, components: int = 1) -> ThroatField:
    field = np.asarray(tuple(float(value) for value in values), dtype=float)
    if components > 1:
        field = np.column_stack([field for _ in range(components)])
    return ThroatField(values=field, label=label)
