from __future__ import annotations

from typing import Any

import numpy as np

from .specs import TransportCaseCollection
from .transport import AdvectionDiffusion, ReactiveTransport, TransientFickianDiffusion, TransientIonicTransport


_ALGORITHMS = {
    "advection_diffusion": AdvectionDiffusion,
    "reactive": ReactiveTransport,
    "fickian": TransientFickianDiffusion,
    "ionic": TransientIonicTransport,
}


def _instantiate_solver(case) -> AdvectionDiffusion:
    try:
        solver_cls = _ALGORITHMS[case.algorithm]
    except KeyError as exc:  # pragma: no cover - guarded by fixture design.
        raise ValueError(f"Unsupported algorithm: {case.algorithm}") from exc
    return solver_cls(case)


def build_public_report(collection: TransportCaseCollection) -> dict[str, Any]:
    cases: list[dict[str, Any]] = []
    for case in collection.cases:
        solver = _instantiate_solver(case)
        outlet_pore = case.boundary_pores[-1]
        solver.set_outflow_BC((outlet_pore,), case.initial_concentration_mol_m3[outlet_pore])
        stage_reports: list[dict[str, Any]] = []
        for stage in case.stages:
            solver.apply_stage(stage)
            result = solver.run(stage.time_step_s, steps=stage.steps)
            concentration = np.asarray(result["concentration"], dtype=float)
            outflow_flux = float(result["outflow_flux"])
            if concentration.size == 0 or not np.all(np.isfinite(concentration)) or not np.isfinite(outflow_flux):
                raise FloatingPointError("stage calculation did not produce finite transport values")
            stage_reports.append(
                {
                    "name": stage.name,
                    "status": "completed",
                    "concentration_mol_m3": [float(value) for value in concentration],
                    "outflow_flux": outflow_flux,
                }
            )
        cases.append(
            {
                "name": case.name,
                "algorithm": case.algorithm,
                "stages": stage_reports,
            }
        )
    return {"analysis": {"cases": cases}}
